{"command":"cat <<'EOF' > test_zip.go
package main

import (
	"archive/zip"
	"fmt"
	"io"
)

func main() {
	r, err := zip.OpenReader("assets/2.test.txt.zip")
	if err != nil {
		fmt.Println("Error:", err)
		return
	}
	defer r.Close()

	for _, f := range r.File {
		fmt.Printf("File: %s, Flags: %x, Method: %d\n", f.Name, f.Flags, f.Method)
		rc, err := f.Open()
		if err != nil {
			fmt.Println("Open error:", err)
			continue
		}
		buf := make([]byte, 16)
		n, _ := io.ReadFull(rc, buf)
		fmt.Printf("Data: %x\n", buf[:n])
		rc.Close()
	}
}
EOF
go run test_zip.go"}

