{"command":"cat <<'EOF' > test_aes.go
package main

import (
	"archive/zip"
	"fmt"
	"os"
)

func main() {
	r, err := zip.OpenReader(os.Args[1])
	if err != nil {
		return
	}
	defer r.Close()

	for _, f := range r.File {
		if f.Method == 99 {
			for i := 0; i < len(f.Extra)-3; i++ {
				if f.Extra[i] == 0x01 && f.Extra[i+1] == 0x99 {
					strength := f.Extra[i+8]
					fmt.Printf("File: %s, AES strength: %d\n", f.Name, strength)
				}
			}
		}
	}
}
EOF
for f in assets/*.zip; do
    go run test_aes.go "$f"
done"}

