{"command":"cat <<'EOF' > main.go
package main

import (
	"archive/zip"
	"bufio"
	"crypto/hmac"
	"crypto/sha1"
	"encoding/hex"
	"fmt"
	"io"
	"os"
	"runtime"
	"sort"
	"strconv"
	"strings"
	"sync"
	"time"
)

type Options struct {
	inputFile          string
	workers            int
	passwordDictionary string
	charset            string
	charsetFile        string
	minPasswordLen     int
	maxPasswordLen     int
	fileNumber         int
	startingPassword   string
	help               bool
	version            bool
}

func printHelp(binName string) {
	fmt.Printf(`Find the password of protected ZIP files

Usage: %s [OPTIONS] --inputFile <inputFile>

Options:
  -i, --inputFile <inputFile>                    path to zip input file
  -w, --workers <workers>                        number of workers
  -p, --passwordDictionary <passwordDictionary>  path to a password dictionary file
  -c, --charset <charset>                        charset to use to generate password [default: lud]
      --charsetFile <charsetFile>                path to a charset file
      --minPasswordLen <minPasswordLen>          minimum password length [default: 1]
      --maxPasswordLen <maxPasswordLen>          maximum password length [default: 10]
      --fileNumber <fileNumber>                  file number in the zip archive [default: 0]
  -s, --startingPassword <startingPassword>      password to start from
  -h, --help                                     Print help
  -V, --version                                  Print version
`, binName)
}

func fileExists(path string) bool {
	_, err := os.Stat(path)
	return err == nil
}

func parseArgs() Options {
	opts := Options{
		charset:        "lud",
		minPasswordLen: 1,
		maxPasswordLen: 10,
		fileNumber:     0,
		workers:        0, // 0 means default
	}

	args := os.Args[1:]
	binName := "executable"
	if len(os.Args) > 0 {
		parts := strings.Split(os.Args[0], "/")
		binName = parts[len(parts)-1]
	}

	for _, arg := range args {
		if arg == "-h" || arg == "--help" {
			printHelp(binName)
			os.Exit(0)
		}
		if arg == "-V" || arg == "--version" {
			fmt.Println("zip-password-finder 0.10.3")
			os.Exit(0)
		}
	}

	i := 0
	for i < len(args) {
		arg := args[i]
		if arg == "-i" || arg == "--inputFile" {
			if i+1 >= len(args) {
				fmt.Fprintf(os.Stderr, "error: a value is required for '--inputFile <inputFile>' but none was supplied\n\nFor more information, try '--help'.\n")
				os.Exit(2)
			}
			opts.inputFile = args[i+1]
			i += 2
			continue
		}
		if arg == "-w" || arg == "--workers" {
			if i+1 >= len(args) {
				fmt.Fprintf(os.Stderr, "error: a value is required for '--workers <workers>' but none was supplied\n\nFor more information, try '--help'.\n")
				os.Exit(2)
			}
			opts.workers, _ = strconv.Atoi(args[i+1])
			i += 2
			continue
		}
		if arg == "-p" || arg == "--passwordDictionary" {
			if i+1 >= len(args) {
				fmt.Fprintf(os.Stderr, "error: a value is required for '--passwordDictionary <passwordDictionary>' but none was supplied\n\nFor more information, try '--help'.\n")
				os.Exit(2)
			}
			opts.passwordDictionary = args[i+1]
			i += 2
			continue
