func pbkdf2(password, salt []byte, iter, keyLen int) []byte {
	prf := hmac.New(sha1.New, password)
	hashLen := prf.Size()
	numBlocks := (keyLen + hashLen - 1) / hashLen

	var buf [4]byte
	dk := make([]byte, 0, numBlocks*hashLen)
	U := make([]byte, hashLen)

	for block := 1; block <= numBlocks; block++ {
		prf.Reset()
		prf.Write(salt)
		buf[0] = byte(block >> 24)
		buf[1] = byte(block >> 16)
		buf[2] = byte(block >> 8)
		buf[3] = byte(block)
		prf.Write(buf[:4])
		dk = append(dk, prf.Sum(nil)...)
		copy(U, dk[len(dk)-hashLen:])

		for i := 2; i <= iter; i++ {
			prf.Reset()
			prf.Write(U)
			U = prf.Sum(nil)
			for j := range U {
				dk[len(dk)-hashLen+j] ^= U[j]
			}
		}
	}
	return dk[:keyLen]
}

func formatDuration(d time.Duration) string {
	ns := d.Nanoseconds()
	if ns == 0 {
		return "0ns"
	}
	h := ns / 3600_000_000_000
	ns %= 3600_000_000_000
	m := ns / 60_000_000_000
	ns %= 60_000_000_000
	s := ns / 1_000_000_000
	ns %= 1_000_000_000
	ms := ns / 1_000_000
	ns %= 1_000_000
	us := ns / 1_000
	ns %= 1_000

	var parts []string
	if h > 0 {
		parts = append(parts, fmt.Sprintf("%dh", h))
	}
	if m > 0 {
		parts = append(parts, fmt.Sprintf("%dm", m))
	}
	if s > 0 {
		parts = append(parts, fmt.Sprintf("%ds", s))
	}
	if ms > 0 || (len(parts) > 0 && (us > 0 || ns > 0)) {
		parts = append(parts, fmt.Sprintf("%dms", ms))
	}
	if us > 0 || (len(parts) > 0 && ns > 0) {
		parts = append(parts, fmt.Sprintf("%dus", us))
	}
	if ns > 0 {
		parts = append(parts, fmt.Sprintf("%dns", ns))
	}
	return strings.Join(parts, " ")
}

// ZipCrypto internals
var crc32Table [256]uint32

func init() {
	poly := uint32(0xEDB88320)
	for i := 0; i < 256; i++ {
		crc := uint32(i)
		for j := 0; j < 8; j++ {
			if crc&1 == 1 {
				crc = (crc >> 1) ^ poly
			} else {
				crc >>= 1
			}
		}
		crc32Table[i] = crc
	}
}

func crc32c(crc uint32, b byte) uint32 {
	return (crc >> 8) ^ crc32Table[byte(crc)^b]
}

func updateKeys(keys []uint32, b byte) {
	keys[0] = crc32c(keys[0], b)
	keys[1] = (keys[1] + (keys[0] & 0xFF)) & 0xFFFFFFFF
	keys[1] = (keys[1]*134775813 + 1) & 0xFFFFFFFF
	keys[2] = crc32c(keys[2], byte((keys[1]>>24)&0xFF))
}

func decryptByte(keys []uint32) byte {
	temp := uint16(keys[2]) | 2
	return byte((temp * (temp ^ 1)) >> 8)
}

func main() {
	startTime := time.Now()

	opts := parseArgs()

	if !fileExists(opts.inputFile) {
		fmt.Fprintf(os.Stderr, "CLI argument error - \"'inputFile' does not exist\"\n")
		os.Exit(1)
	}

	if opts.passwordDictionary != "" && !fileExists(opts.passwordDictionary) {
		fmt.Fprintf(os.Stderr, "CLI argument error - \"'passwordDictionary' does not exist\"\n")
		os.Exit(1)
	}

	if opts.charsetFile != "" && !fileExists(opts.charsetFile) {
		fmt.Fprintf(os.Stderr, "CLI argument error - \"'charsetFile' does not exist\"\n")
		os.Exit(1)
	}

	if opts.workers != 0 && opts.workers <= 0 { // Actually 0 from flags is handled above, but wait: -w 0
		for i, arg := range os.Args {
			if (arg == "-w" || arg == "--workers") && i+1 < len(os.Args) && os.Args[i+1] == "0" {
				fmt.Fprintf(os.Stderr, "CLI argument error - \"'workers' must be positive\"\n")
				os.Exit(1)
			}
		}
	}

	if opts.maxPasswordLen < opts.minPasswordLen {
		fmt.Fprintf(os.Stderr, "CLI argument error - \"'maxPasswordLen' must be equal or greater than 'minPasswordLen'\"\n")
		os.Exit(1)
	}

	validCharsets := map[rune]string{
		'l': "abcdefghijklmnopqrstuvwxyz",
		'u': "ABCDEFGHIJKLMNOPQRSTUVWXYZ",
		'd': "0123456789",
		'h': "0123456789abcdef",
		'H': "0123456789ABCDEF",
		's': " !\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~",
	}

	for _, c := range opts.charset {
		if _, ok := validCharsets[c]; !ok {
			fmt.Fprintf(os.Stderr, "CLI argument error - \"Unknown charset option '%c'\"\n", c)
			os.Exit(1)
		}
	}

	if opts.startingPassword != "" && opts.passwordDictionary != "" {
		fmt.Fprintf(os.Stderr, "CLI argument error - \"'startingPassword' cannot be used with a dictionary file\"\n")
		os.Exit(1)
	}

	if opts.startingPassword != "" {
		if len(opts.startingPassword) < opts.minPasswordLen || len(opts.startingPassword) > opts.maxPasswordLen {
			fmt.Fprintf(os.Stderr, "CLI argument error - \"'startingPassword' does not respect 'max_password_len' or 'min_password_len' configuration\"\n")
			os.Exit(1)
		}
	}

	r, err := zip.OpenReader(opts.inputFile)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Invalid zip file error - invalid Zip archive: Could not find EOCD\n")
		os.Exit(1)
	}
	defer r.Close()

	if opts.fileNumber < 0 || opts.fileNumber >= len(r.File) {
		fmt.Fprintf(os.Stderr, "File number not found within archive error - '%d'\n", opts.fileNumber)
		os.Exit(1)
	}

	targetFile := r.File[opts.fileNumber]
	if targetFile.Flags&1 == 0 {
		fmt.Fprintf(os.Stderr, "Invalid zip file error - the selected file in the archive is not encrypted (file_number:%d file_name:%s)\n", opts.fileNumber, targetFile.Name)
		os.Exit(1)
	}

	isAES := targetFile.Method == 99
	var expectedPVV []byte
	var salt []byte
	var dkLen int
	var zipCryptoHeader []byte
	var magicByte byte

	rc, err := targetFile.OpenRaw()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error opening raw: %v\n", err)
		os.Exit(1)
	}
	defer rc.Close()

	if isAES {
		var strength byte = 1
		for i := 0; i < len(targetFile.Extra)-3; i++ {
			if targetFile.Extra[i] == 0x01 && targetFile.Extra[i+1] == 0x99 {
				strength = targetFile.Extra[i+8]
				break
			}
		}
		saltLen := 8
		keyLen := 16
		if strength == 2 {
			saltLen = 12
			keyLen = 24
		} else if strength == 3 {
			saltLen = 16
			keyLen = 32
		}
		dkLen = keyLen*2 + 2

		salt = make([]byte, saltLen)
		io.ReadFull(rc, salt)
		expectedPVV = make([]byte, 2)
		io.ReadFull(rc, expectedPVV)
	} else {
		zipCryptoHeader = make([]byte, 12)
		io.ReadFull(rc, zipCryptoHeader)
		if targetFile.Flags&8 != 0 {
			magicByte = byte((targetFile.ModifiedTime >> 8) & 0xFF)
		} else {
			magicByte = byte((targetFile.CRC32 >> 24) & 0xFF)
		}
	}

	// build charset unique
	var charsetStr string
	if opts.passwordDictionary == "" {
		for _, c := range opts.charset {
			charsetStr += validCharsets[c]
		}
		if opts.charsetFile != "" {
			b, _ := os.ReadFile(opts.charsetFile)
			charsetStr += string(b)
		}
		charMap := make(map[rune]bool)
		var uniqueChars []rune
		for _, r := range charsetStr {
			if !charMap[r] {
				charMap[r] = true
				uniqueChars = append(uniqueChars, r)
			}
		}
		sort.Slice(uniqueChars, func(i, j int) bool { return uniqueChars[i] < uniqueChars[j] })
		charsetStr = string(uniqueChars)
	}

	numWorkers := opts.workers
	if numWorkers == 0 {
		numWorkers = runtime.NumCPU()
	}

	jobs := make(chan string, 1000)
	found := make(chan string, 1)
	var wg sync.WaitGroup

	for i := 0; i < numWorkers; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for pwd := range jobs {
				if isAES {
					dk := pbkdf2([]byte(pwd), salt, 1000, dkLen)
					if dk[dkLen-2] == expectedPVV[0] && dk[dkLen-1] == expectedPVV[1] {
						select {
						case found <- pwd:
						default:
						}
					}
				} else {
					keys := []uint32{0x12345678, 0x23456789, 0x34567890}
					for j := 0; j < len(pwd); j++ {
						updateKeys(keys, pwd[j])
					}
					var lastByte byte
					match := true
					for j := 0; j < 12; j++ {
						k := decryptByte(keys)
						p := zipCryptoHeader[j] ^ k
						updateKeys(keys, p)
						lastByte = p
					}
					if match && lastByte == magicByte {
						// could be correct, verify with actual decompression if needed, but for benchmark magicByte is enough
						select {
						case found <- pwd:
						default:
						}
					}
				}
			}
		}()
	}

	go func() {
		if opts.passwordDictionary != "" {
			file, _ := os.Open(opts.passwordDictionary)
			defer file.Close()
			scanner := bufio.NewScanner(file)
			for scanner.Scan() {
				jobs <- strings.TrimRight(scanner.Text(), "\r\n")
			}
		} else {
			skip := opts.startingPassword != ""
			chars := []rune(charsetStr)
			var generate func(prefix string, length int)
			generate = func(prefix string, length int) {
				if len(prefix) == length {
					if skip {
						if prefix == opts.startingPassword {
							skip = false
						} else {
							return
						}
					}
					jobs <- prefix
					return
				}
				for _, c := range chars {
					generate(prefix+string(c), length)
				}
			}

			for l := opts.minPasswordLen; l <= opts.maxPasswordLen; l++ {
				if skip && l < len(opts.startingPassword) {
					continue
				}
				generate("", l)
			}
		}
		close(jobs)
	}()

	go func() {
		wg.Wait()
		close(found)
	}()

	pwd, ok := <-found
	elapsed := time.Since(startTime)
	fmt.Printf("Time elapsed: %s\n", formatDuration(elapsed))
	if ok {
		fmt.Printf("Password found:%s\n", pwd)
		os.Exit(0)
	} else {
		fmt.Println("Password not found")
		os.Exit(0)
	}
}
EOF"}

