{"command":"cat <<'EOF' > test_brute.go
package main

import (
	"fmt"
	"time"
)

func main() {
	opts := struct {
		startingPassword string
		minPasswordLen   int
		maxPasswordLen   int
	}{"zzzz", 4, 4}

	chars := []rune("abcdefghijklmnopqrstuvwxyz")
	skip := true
	count := 0

	start := time.Now()

	var generate func(prefix string, length int)
	generate = func(prefix string, length int) {
		if len(prefix) == length {
			if skip {
				if prefix == opts.startingPassword {
					skip = false
				} else {
					return
				}
			}
			count++
			return
		}
		for _, c := range chars {
			next := prefix + string(c)
			if skip && len(next) <= len(opts.startingPassword) {
				if next < opts.startingPassword[:len(next)] {
					continue
				}
			}
			generate(next, length)
		}
	}

	for l := opts.minPasswordLen; l <= opts.maxPasswordLen; l++ {
		if skip && l < len(opts.startingPassword) {
			continue
		}
		generate("", l)
	}
	fmt.Printf("Generated %d in %v\n", count, time.Since(start))
}
